public static AmountCur calculate(
    SalesLine   _salesLine,
    SalesTable  _salesTable)
{
    // Skip returned orders
    if (_salesTable.SalesType == SalesType::ReturnItem)
    {
        return -1;
    }

    real pickedCases       = _salesLine.metDisplayPickedCases();
    real pickedBrokenCases = _salesLine.metDisplayPickedBrokenCases();

    // Fallback: charge-through / charge-only
    if (pickedCases == 0 && pickedBrokenCases == 0)
    {
        return -1;
    }

    InventTransId        targetInventTransId  = _salesLine.InventTransId;
    InventItemSalesSetup inventItemSalesSetup = InventItemSalesSetup::find(
                                                    _salesLine.ItemId,
                                                    _salesLine.InventDimId);

    // --- Sum all components ---
    real basePriceSum   = METPickedQtyInvoiceCalculator::sumByEnum(targetInventTransId, METPriceComponent::BasePrice);
    real marginsSum     = METPickedQtyInvoiceCalculator::sumByEnum(targetInventTransId, METPriceComponent::Margins);
    real lineChargesSum = METPickedQtyInvoiceCalculator::sumByEnum(targetInventTransId, METPriceComponent::LineCharges);
    real unitPriceSum   = METPickedQtyInvoiceCalculator::sumByEnum(targetInventTransId, METPriceComponent::UnitPrice);
    real netAmountSum   = METPickedQtyInvoiceCalculator::sumByEnum(targetInventTransId, METPriceComponent::NetAmount);
    real discountsSum   = METPickedQtyInvoiceCalculator::sumByEnum(targetInventTransId, METPriceComponent::Discounts);

    // Discounts subtract, everything else adds
    real netComponentValue = basePriceSum
                           + marginsSum
                           + lineChargesSum
                           + unitPriceSum
                           + netAmountSum
                           - discountsSum;

    // --- UOM Conversion ---
    // convert(1, METSalesUnit → EA)
    // e.g. 1 Outer12 → EA = 1/12 = 0.0833
    real convertedValue = 1;

    RecId uomRecId = UnitOfMeasure::unitOfMeasureIdBySymbol(_salesLine.SalesUnit);

    if (_salesLine.SalesUnit == 'ea'
        && UnitOfMeasureConverter::canBeConverted(
            UnitOfMeasure::unitOfMeasureIdBySymbol(inventItemSalesSetup.METSalesUnit),
            uomRecId,
            InventTable::itemProduct(_salesLine.ItemId)))
    {
        convertedValue = UnitOfMeasureConverter::convert(
            1,
            UnitOfMeasure::unitOfMeasureIdBySymbol(inventItemSalesSetup.METSalesUnit),
            uomRecId,
            NoYes::No,
            InventTable::itemProduct(_salesLine.ItemId),
            NoYes::No);
    }

    // --- FSD Formula ---
    // Picked Cases        : pickedCases x netComponentValue
    // Picked Broken Cases : pickedBrokenCases x convertedValue x netComponentValue
    real pickedCasesAmt       = pickedCases * netComponentValue;
    real pickedBrokenCasesAmt = pickedBrokenCases * convertedValue * netComponentValue;

    return pickedCasesAmt + pickedBrokenCasesAmt;
}

// Single reusable sum method
private static real sumByEnum(
    InventTransId       _inventTransId,
    METPriceComponent   _priceComponent)
{
    METSalesLinePriceComponent  priceComponent;
    METComponentCode            componentCode;

    select sum(Value) from priceComponent
        where priceComponent.InventTransId == _inventTransId
        join componentCode
            where priceComponent.Component     == componentCode.Component
               && componentCode.PriceComponent == _priceComponent;

    return priceComponent.Value;
}
